use reqwest;
use scraper::{Html, Selector};

// Function to scrape a webpage
fn scrape_website(url: &str) -> Result<String, reqwest::Error> {
    let response = reqwest::get(url)?;
    let body = response.text()?;

    // Use the scraper library to parse the HTML
    let document = Html::parse_document(&body);

    // Example: Extract all the text from the page
    let mut text = String::new();
    for element in document.select("body") {
        for child in element.children() {
            text.push_str(&child.value().text().unwrap());
        }
    }

    Ok(text)
}

fn main() -> Result<(), reqwest::Error> {
    let url = "https://www.example.com"; // Replace with the URL you want to scrape

    match scrape_website(url) {
        Ok(text) => {
            println!("Scraped text from {}:", url);
            println!("{}", text);
        }
        Err(e) => {
            eprintln!("Error scraping {}: {}", url, e);
        }
    }

    Ok(())
}
```

