    func fetchData() {
        guard let view = myView else {
            print("Error: View not found.")
            return
        }

        // Example: Extract text from all labels within the view
        for subview in view.subviews {
            if let label = subview as? UILabel {
                print("Label Text: \(label.text ?? "No text")")
            } else if let button = subview as? UIButton {
                print("Button Title: \(button.title(forState: .normal) ?? "No title")")
            }
        }
    }
}


