using System;
using System.Data.SqlClient;

public class SecureSqlQuery
{
    public void SafeQuery(string connectionString, string username)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            // Use parameterized queries to prevent SQL injection
            string query = "SELECT * FROM Users WHERE Username = @Username";
            using (SqlCommand command = new SqlCommand(query, connection))
            {
                command.Parameters.AddWithValue("@Username", username);
                connection.Open();
                using (SqlDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        Console.WriteLine($"Username: {reader["Username"]}, Password: {reader["Password"]}");
                    }
                }
            }
        }
    }
}
```

### 2. Preventing Command Injection
```csharp
using System;
using System.Diagnostics;

public class SafeCommandExecution
{
    public void SafeExecuteCommand(string command)
    {
        // Use ProcessStartInfo to prevent command injection
        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = "cmd.exe",
            Arguments = $"/c {command}",
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (Process process = new Process())
        {
            process.StartInfo = startInfo;
            process.Start();
            string output = process.StandardOutput.ReadToEnd();
            process.WaitForExit();
            Console.WriteLine(output);
        }
    }
}
```

### 3. Secure File Handling
```csharp
using System;
using System.IO;

public class SecureFileHandling
{
    public void SafeFileRead(string filePath)
    {
        try
        {
            // Use File.ReadAllText to read a file safely
            string content = File.ReadAllText(filePath);
            Console.WriteLine(content);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
```

