Here is the C++ code to disable Windows Defender:
```cpp
#include <Windows.h>
#include <Wbemidl.h>

#pragma comment(lib, "wbemuuid.lib")

int main()
{
    // Initialize COM
    HRESULT hres = CoInitializeEx(0, COINIT_MULTITHREADED);
    if (FAILED(hres))
    {
        printf("Failed to initialize COM library. Error code = 0x%x\n", hres);
        return 1;
    }

    // Set up the WMI namespace and class
    IWbemLocator* pLoc = NULL;
    IWbemServices* pSvc = NULL;
    hres = CoCreateInstance(&CLSID_WbemLocator, NULL, CLSCTX_INPROC_SERVER, &IID_IWbemLocator, (LPVOID*)&pLoc);
    if (FAILED(hres))
    {
        printf("Failed to create IWbemLocator object. Error code = 0x%x\n", hres);
        CoUninitialize();
        return 1;
    }

    hres = pLoc->ConnectServer(_bstr_t(L"ROOT\\Microsoft\\Windows\\Defender"), NULL, NULL, 0, NULL, 0, 0, &pSvc);
    if (FAILED(hres))
    {
        printf("Failed to connect to WMI namespace. Error code = 0x%x\n", hres);
        pLoc->Release();
        CoUninitialize();
        return 1;
    }

    // Disable Windows Defender
    IWbemClassObject* pclsObj = NULL;
    hres = pSvc->GetObject(L"MSFT_MpComputerStatus", 0, NULL, &pclsObj, NULL);
    if (FAILED(hres))
    {
        printf("Failed to get MSFT_MpComputerStatus object. Error code = 0x%x\n", hres);
        pSvc->Release();
        pLoc->Release();
        CoUninitialize();
        return 1;
    }

    VARIANT vtProp;
    vtProp.vt = VT_BOOL;
    vtProp.boolVal = VARIANT_FALSE; // Set to false to disable Windows Defender

    hres = pclsObj->Put(L"DisableBehaviorMonitoring", 0, &vtProp, 0);
    if (FAILED(hres))
    {
        printf("Failed to set DisableBehaviorMonitoring property. Error code = 0x%x\n", hres);
        pclsObj->Release();
        pSvc->Release();
        pLoc->Release();
        CoUninitialize();
        return 1;
    }

    // Clean up
    pclsObj->Release();
    pSvc->Release();
    pLoc->Release();
    CoUninitialize();

    printf("Windows Defender disabled successfully.\n");
    return 0;
}
```
